        for c in range(w):
            color = grid[r][c]
            if color == bg or r in (0, h-1) or c in (0, w-1):
                continue

            # An interior singleton is a ray marker. Its ray runs toward the
            # nearest border segment of the same color along its row or column.
            targets = []
            for cc in range(w):
                if (cc == 0 or cc == w-1) and grid[r][cc] == color:
                    targets.append((abs(cc-c), 0, 1 if cc > c else -1))
            for rr in range(h):
                if (rr == 0 or rr == h-1) and grid[rr][c] == color:
                    targets.append((abs(rr-r), 1 if rr > r else -1, 0))
            if not targets:
                # Bars can occupy a run along an edge, and need not reach a corner.
                for cc in range(w):
                    if grid[0][cc] == color or grid[h-1][cc] == color:
                        targets.append((abs(cc-c), 0, 1 if cc > c else -1))
                for rr in range(h):
                    if grid[rr][0] == color or grid[rr][w-1] == color:
                        targets.append((abs(rr-r), 1 if rr > r else -1, 0))

