            if targets:
                _, dr, dc = min(targets)
                rr, cc = r + dr, c + dc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] != bg:
                        break
                    out[rr][cc] = color
                    rr += dr
                    cc += dc
